const createRefund = `-- name: CreateRefund :one
INSERT INTO refunds (order_id, user_id, amount, destination, rule, reason, operator_id)
VALUES ($1, $2, $3, $4, $5, $6, $7)
RETURNING id, order_id, amount, destination, status, gateway_ref, reason, operator_id, created_at, rule, user_id
`

type CreateRefundParams struct {
	OrderID     int64   `json:"order_id"`
	UserID      int64   `json:"user_id"`
	Amount      int64   `json:"amount"`
	Destination string  `json:"destination"`
	Rule        string  `json:"rule"`
	Reason      *string `json:"reason"`
	OperatorID  *int64  `json:"operator_id"`
}

// ⚠️ user_id 是 0016 加的**冗余**列（NOT NULL，无默认值），必须显式写 ——
//
//	它存在的唯一理由是让 refunds_cooling_off_once 这条部分唯一索引成立，
//	「冷静期退款一生一次」因此是数据库拒绝，而不是应用代码的自觉（ADR 0013 §6.1）。
//	调用方必须传 orders.user_id，两者不一致会让那条唯一索引失效。
//	rule 有 DEFAULT 'manual'，但同样显式传：走的是哪一档退款规则是审计要回答的问题，
//	让它默认成 'manual' 等于把 cooling_off 的一生一次悄悄绕过去。
func (q *Queries) CreateRefund(ctx context.Context, arg CreateRefundParams) (Refund, error) {
	row := q.db.QueryRow(ctx, createRefund,
		arg.OrderID,
		arg.UserID,
		arg.Amount,
		arg.Destination,
		arg.Rule,
		arg.Reason,
		arg.OperatorID,
	)
	var i Refund
	err := row.Scan(
		&i.ID,
		&i.OrderID,
		&i.Amount,
		&i.Destination,
		&i.Status,
		&i.GatewayRef,
		&i.Reason,
		&i.OperatorID,
		&i.CreatedAt,
		&i.Rule,
		&i.UserID,
	)
	return i, err
}

const findUnbalancedLedgerEntries = `-- name: FindUnbalancedLedgerEntries :many
SELECT entry_id, sum(amount)::bigint AS imbalance
FROM ledger_lines
GROUP BY entry_id
HAVING sum(amount) <> 0
`

type FindUnbalancedLedgerEntriesRow struct {
	EntryID   int64 `json:"entry_id"`
	Imbalance int64 `json:"imbalance"`
}

// 巡检：借贷不平的分录。返回非空行 = 立即告警。
func (q *Queries) FindUnbalancedLedgerEntries(ctx context.Context) ([]FindUnbalancedLedgerEntriesRow, error) {
	rows, err := q.db.Query(ctx, findUnbalancedLedgerEntries)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []FindUnbalancedLedgerEntriesRow{}
	for rows.Next() {
		var i FindUnbalancedLedgerEntriesRow
		if err := rows.Scan(&i.EntryID, &i.Imbalance); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

